/**
 * @yavi/widgets/server/express
 *
 * Drop-in Express router.
 *
 * Usage (server.ts / server.js):
 *
 *   import express from 'express';
 *   import { createExpressRouter } from '@yavi/widgets/server/express';
 *
 *   const app = express();
 *   app.use(express.json());
 *   app.use('/api/yavi', createExpressRouter());
 *   // No config needed — all defaults are built in.
 *
 * Wires up:
 *   GET  /api/yavi/widget/:id
 *   POST /api/yavi/session
 *   GET  /api/yavi/namespaces/:workspaceId
 *   POST /api/yavi/summary-stream   ← SSE
 *   POST /api/yavi/qna-chat
 *   POST /api/yavi/structured-chat
 */

import { createRequire } from 'module';
import type { Router as ExpressRouter } from 'express';
import type { YaviServerConfig } from '../widgets/summary/types';

type Req = {
  params: Record<string, string>;
  body: any;
  headers: Record<string, string | string[] | undefined>;
  url: string;
};
type Res = {
  json: (body: any) => void;
  status: (code: number) => Res;
  setHeader: (k: string, v: string) => void;
  flushHeaders: () => void;
  write: (chunk: string) => void;
  end: () => void;
};
type NextFn = (err?: any) => void;

// ─── Router factory ───────────────────────────────────────────────────────────

// ─── Built-in defaults (consumers don't need to configure these) ─────────────
const DEFAULTS = {
  yaviRagUrl:        'https://apirag.dev5.yavi.ai',
  yaviStructuredUrl: 'https://apirag.dev5.yavi.ai/structured-json-rag',
  mongoUri:          'mongodb://localhost:27017/new_ui',
  defaultLlmConfig:  'gpt-4o-mini',
};

export function createExpressRouter(config: YaviServerConfig = {}) {
  const {
    yaviRagUrl        = DEFAULTS.yaviRagUrl,
    yaviStructuredUrl = DEFAULTS.yaviStructuredUrl,
    mongoUri          = DEFAULTS.mongoUri,
    defaultLlmConfig  = DEFAULTS.defaultLlmConfig,
  } = config;

  // Resolve express from the consuming app to support local file-linked installs.
  const nodeRequire = createRequire(`${process.cwd()}/package.json`);
  const expressModule = nodeRequire('express') as { Router: () => ExpressRouter };
  const router: ExpressRouter = expressModule.Router();

  const getToken = (req: Req): string =>
    (
      (req.headers['authorization'] as string | undefined) ?? ''
    ).replace('Bearer ', '');

  const unauthorized = (res: Res) =>
    res.status(401).json({ error: 'Unauthorized' });

  // ── GET /widget/:id ──────────────────────────────────────────────────────
  router.get('/widget/:id', async (req: Req, res: Res, next: NextFn) => {
    const token = getToken(req);
    if (!token) return unauthorized(res);
    try {
      const result = await getWidgetById(req.params.id, mongoUri);
      res.json(result);
    } catch (e) {
      next(e);
    }
  });

  // ── GET /namespaces/:workspaceId ─────────────────────────────────────────
  router.get('/namespaces/:workspaceId', async (req: Req, res: Res, next: NextFn) => {
    const token = getToken(req);
    if (!token) return unauthorized(res);
    try {
      const result = await getNamespacesByWorkspace(
        req.params.workspaceId,
        token,
        mongoUri
      );
      res.json(result);
    } catch (e) {
      next(e);
    }
  });

  // ── POST /session ────────────────────────────────────────────────────────
  router.post('/session', async (req: Req, res: Res, next: NextFn) => {
    const token = getToken(req);
    if (!token) return unauthorized(res);
    try {
      const {
        type,
        yaviLlmConfigName,
        yavi_llm_config_name,
        datasetId,
        dataset_id,
        llm_parameters,
        user_id,
      } = req.body as {
        type?: 'unstructured' | 'structured';
        yaviLlmConfigName?: string;
        yavi_llm_config_name?: string;
        datasetId?: string;
        dataset_id?: string;
        llm_parameters?: Record<string, unknown>;
        user_id?: string;
      };
      const resolvedDatasetId = datasetId ?? dataset_id;
      const model = yaviLlmConfigName ?? defaultLlmConfig;
      const structuredModel = yaviLlmConfigName ?? yavi_llm_config_name ?? defaultLlmConfig;
      const sessionType = type ?? (resolvedDatasetId ? 'structured' : 'unstructured');

      // Decode userId from token
      let userId = '';
      try {
        const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString('utf8'));
        userId = payload.sub ?? '';
      } catch { /* ignore */ }

      if (sessionType === 'structured') {
        if (!resolvedDatasetId) {
          return res.status(400).json({ error: 'datasetId required' });
        }
        const r = await fetch(`${yaviStructuredUrl}/api/v2/session`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
          body: JSON.stringify({
            dataset_id: resolvedDatasetId,
            yavi_llm_config_name: structuredModel,
            yavi_embedding_config_name: process.env.AZURE_YAVI_EMBEDDING_CONFIG_NAME ?? 'azure-embedding-small',
            llm_parameters: llm_parameters ?? { temperature: 0.7, max_tokens: 2000 },
            user_id: user_id ?? userId,
          }),
        });
        res.status(r.status).json(await r.json());
        return;
      }

      // UnStructured

      const r = await fetch(`${yaviRagUrl}/rag/api/v2/session`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({
          bot_mode: 'standard_v2',
          yavi_llm_config_name: model,
          llm_parameters: { frequency_penalty: 0, presence_penalty: 0, temperature: 0.7, max_tokens: 2000, top_p: 1 },
          user_id: userId,
        }),
      });
      res.status(r.status).json(await r.json());
    } catch (e) {
      next(e);
    }
  });

  // ── POST /summary-stream (SSE) ───────────────────────────────────────────
  router.post('/summary-stream', async (req: Req, res: Res, next: NextFn) => {
    const token = getToken(req);
    if (!token) return unauthorized(res);

    const { documentIds, customPrompt, yaviLlmConfigName, separate } = req.body as {
      documentIds: string[];
      customPrompt?: string;
      yaviLlmConfigName?: string;
      separate?: boolean;
    };

    if (!documentIds?.length) {
      return res.status(400).json({ error: 'documentIds required' });
    }

    const separateFlag = separate ?? false;
    const model = yaviLlmConfigName ?? defaultLlmConfig;
    const promptToUse = buildSummaryPrompt(customPrompt, separateFlag);

    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Cache-Control', 'no-cache, no-transform');
    res.setHeader('Connection', 'keep-alive');
    res.setHeader('X-Accel-Buffering', 'no');
    res.flushHeaders();

    try {
      const upstream = await fetch(`${yaviRagUrl}/content_generation/api/v1/summary`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          custom_prompt: promptToUse,
          document_ids: documentIds,
          separate: separateFlag,
          streaming: true,
          yavi_llm_config_name: model,
        }),
      });

      if (!upstream.ok) {
        const err = await upstream.text();
        res.write(`data: ${JSON.stringify({ error: err })}\n\n`);
        res.end();
        return;
      }

      const reader = upstream.body!.getReader();
      const dec = new TextDecoder();
      let buf = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buf += dec.decode(value, { stream: true });
        const lines = buf.split('\n');
        buf = lines.pop() ?? '';
        for (const line of lines) {
          let json = line.trim();
          if (!json) continue;
          if (json.startsWith('data: ')) json = json.slice(6).trim();
          if (!json || json === '[DONE]') {
            if (json === '[DONE]') res.write('data: [DONE]\n\n');
            continue;
          }
          try {
            const parsed = JSON.parse(json);
            if (separateFlag) {
              const valid = ['document_start', 'document_chunk', 'document_complete', 'session_complete'];
              if (valid.includes(parsed.type)) res.write(`data: ${JSON.stringify(parsed)}\n\n`);
            } else {
              if (parsed.type === 'chunk' && parsed.content) {
                res.write(`data: ${JSON.stringify({ content: parsed.content })}\n\n`);
              }
            }
          } catch { /* skip */ }
        }
      }

      res.write('data: [DONE]\n\n');
      res.end();
    } catch (e) {
      next(e);
    }
  });

  // ── POST /structured-chat ────────────────────────────────────────────────
  router.post('/structured-chat', async (req: Req, res: Res, next: NextFn) => {
    const token = getToken(req);
    if (!token) return unauthorized(res);
    const {
      sessionId,
      prompt,
      question,
      customPrompt,
      custom_prompt,
      addToHistory,
      add_to_history,
      useSystemPrompt,
      use_system_prompt,
    } = req.body as {
      sessionId: string;
      prompt?: string;
      question?: string;
      customPrompt?: string;
      custom_prompt?: string;
      addToHistory?: boolean;
      add_to_history?: boolean;
      useSystemPrompt?: boolean;
      use_system_prompt?: boolean;
    };
    if (!sessionId) return res.status(400).json({ error: 'sessionId required' });
    try {
      const r = await fetch(`${yaviStructuredUrl}/api/v2/session/${sessionId}/chat`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({
          question:
            question?.trim() ||
            `You are an expert document analyst. Provide a structured markdown summary. ${prompt ?? ''}`,
          add_to_history: add_to_history ?? addToHistory ?? false,
          use_system_prompt: use_system_prompt ?? useSystemPrompt ?? true,
          custom_prompt:
            custom_prompt ?? customPrompt ?? buildStructuredPrompt(prompt ?? question),
        }),
      });
      const data = await r.json();
      res.json({ answer: data?.explanation ?? data?.answer ?? '' });
    } catch (e) {
      next(e);
    }
  });

  // ── POST /qna-chat ────────────────────────────────────────────────────────
  router.post('/qna-chat', async (req: Req, res: Res, next: NextFn) => {
    const token = getToken(req);
    if (!token) return unauthorized(res);
    const {
      sessionId,
      question,
      documentIds,
      namespace,
      topK,
      customPrompt,
    } = req.body as {
      sessionId: string;
      question: string;
      documentIds?: string[];
      namespace?: string;
      topK?: number;
      customPrompt?: string;
    };

    if (!sessionId || !question) {
      return res.status(400).json({ error: 'sessionId and question are required' });
    }
    if (!namespace) {
      return res.status(400).json({ error: 'namespace is required for qna-chat' });
    }

    try {
      const vectorStore: any = {
        context_variable: 'context1',
        query: question,
        rag_processor: { top_k: topK ?? 25 },
        vector_db_config: {
          connection_string: '',
          dimensions: 1536,
          namespace,
          vector_db_type: 'neondb',
        },
      };

      if (documentIds && documentIds.length > 0) {
        vectorStore.filter_by = {
          document_id: {
            $in: documentIds,
          },
        };
      }

      const baseQuestion = customPrompt
        ? `${question}\n\n${customPrompt}`
        : question;

      const payload = {
        add_to_history: false,
        use_base_system_prompt: true,
        prompt: `${baseQuestion} \n\n{{context1}}. Do not include context references.`,
        vector_stores: [vectorStore],
      };

      const upstream = await fetch(`${yaviRagUrl}/rag/api/v2/chat/${sessionId}`, {
        method: 'POST',
        headers: {
          Accept: 'application/json',
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(payload),
      });

      const text = await upstream.text();
      if (!upstream.ok) {
        return res.status(upstream.status).json({ error: text });
      }

      const data = JSON.parse(text);
      const finalText = data?.final_answer_text || 'No answer available.';
      const allRefs = data?.metadatas
        ? (Object.values(data.metadatas).flat() as any[])
        : [];
      const answer =
        allRefs.length > 0
          ? `${finalText}\n\nb_box${JSON.stringify(allRefs)}`
          : finalText;

      res.json({ answer });
    } catch (e) {
      next(e);
    }
  });

  // ── GET /proxy/rag/* ─────────────────────────────────────────────────────
  router.get(/^\/proxy\/rag\/(.*)$/, async (req: Req, res: Res, next: NextFn) => {
    const token = getToken(req);
    if (!token) return unauthorized(res);
    try {
      const path = req.params[0] || '';
      const qs = req.url.split('?')[1] ? `?${req.url.split('?')[1]}` : '';
      const targetUrl = `${yaviRagUrl}/${path}${qs}`;
      const r = await fetch(targetUrl, {
        method: 'GET',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
      });
      const text = await r.text();
      res.status(r.status).setHeader('Content-Type', r.headers.get('Content-Type') || 'application/json');
      res.write(text);
      res.end();
    } catch (e) {
      next(e);
    }
  });

  // ── GET /proxy/structured/* ──────────────────────────────────────────────
  router.get(/^\/proxy\/structured\/(.*)$/, async (req: Req, res: Res, next: NextFn) => {
    const token = getToken(req);
    if (!token) return unauthorized(res);
    try {
      const path = req.params[0] || '';
      const qs = req.url.split('?')[1] ? `?${req.url.split('?')[1]}` : '';
      const targetUrl = `${yaviStructuredUrl}/${path}${qs}`;
      const r = await fetch(targetUrl, {
        method: 'GET',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
      });
      const text = await r.text();
      res.status(r.status).setHeader('Content-Type', r.headers.get('Content-Type') || 'application/json');
      res.write(text);
      res.end();
    } catch (e) {
      next(e);
    }
  });

  // ── POST /proxy/rag/* ────────────────────────────────────────────────────
  router.post(/^\/proxy\/rag\/(.*)$/, async (req: Req, res: Res, next: NextFn) => {
    const token = getToken(req);
    if (!token) return unauthorized(res);
    try {
      const path = req.params[0] || '';
      const qs = req.url.split('?')[1] ? `?${req.url.split('?')[1]}` : '';
      const targetUrl = `${yaviRagUrl}/${path}${qs}`;
      const r = await fetch(targetUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify(req.body),
      });
      const text = await r.text();
      res.status(r.status).setHeader('Content-Type', r.headers.get('Content-Type') || 'application/json');
      res.write(text);
      res.end();
    } catch (e) {
      next(e);
    }
  });

  // ── POST /proxy/structured/* ─────────────────────────────────────────────
  router.post(/^\/proxy\/structured\/(.*)$/, async (req: Req, res: Res, next: NextFn) => {
    const token = getToken(req);
    if (!token) return unauthorized(res);
    try {
      const path = req.params[0] || '';
      const qs = req.url.split('?')[1] ? `?${req.url.split('?')[1]}` : '';
      const targetUrl = `${yaviStructuredUrl}/${path}${qs}`;
      const r = await fetch(targetUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify(req.body),
      });
      const text = await r.text();
      res.status(r.status).setHeader('Content-Type', r.headers.get('Content-Type') || 'application/json');
      res.write(text);
      res.end();
    } catch (e) {
      next(e);
    }
  });

  return router;
}

// ─── Mongo helpers ────────────────────────────────────────────────────────────

async function connectMongo(uri: string) {
  const { MongoClient } = await import('mongodb');
  const client = new MongoClient(uri);
  await client.connect();
  return client;
}

async function getWidgetById(id: string, mongoUri: string) {
  const client = await connectMongo(mongoUri);
  try {
    const { ObjectId } = await import('mongodb');
    const db = client.db();
    const collections = [db.collection('widgets'), db.collection('widgetconfigs')];
    let doc: any = null;
    const isObjectId = /^[a-f\d]{24}$/i.test(id);

    for (const col of collections) {
      if (doc) break;
      if (isObjectId) {
        doc = await col.findOne({ _id: new ObjectId(id) });
      }
      if (!doc) {
        doc = await col.findOne({ $or: [{ widgetId: id }, { id: id }] } as any);
      }
    }

    if (!doc) return { success: false, message: 'Widget not found' };
    return {
      success: true,
      widget: {
        ...(doc.widgetData ?? doc),
        _id: doc._id.toString(),
        structuredDataConfig: doc.structuredDataConfig ?? null,
      },
    };
  } finally {
    await client.close();
  }
}

async function getNamespacesByWorkspace(workspaceId: string, token: string, mongoUri: string) {
  let userId = '';
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString('utf8'));
    userId = payload.sub ?? '';
  } catch { /* ignore */ }

  const client = await connectMongo(mongoUri);
  try {
    const pipeline: object[] = [
      { $match: { workspaceId, userId } },
      { $addFields: { fileIdString: { $toString: '$_id' } } },
      {
        $lookup: {
          from: 'fileprocessings',
          localField: 'fileIdString',
          foreignField: 'fileId',
          as: 'processingData',
        },
      },
      { $unwind: { path: '$processingData', preserveNullAndEmptyArrays: false } },
      {
        $match: {
          'processingData.processingstep': {
            $elemMatch: { step: 'vectorizing', status: 'completed' },
          },
          'processingData.api_responses.vectorizing.namespace': { $exists: true, $ne: null },
          'processingData.api_responses.vectorizing.response_body.vector_status': 'completed',
        },
      },
      {
        $group: {
          _id: '$processingData.api_responses.vectorizing.namespace',
          count: { $sum: 1 },
          workspaceName: { $first: '$workspaceName' },
          sources: {
            $push: {
              file_id: '$processingData.yaviFileId',
              document_id: '$processingData.api_responses.extraction.response_body.document_id',
              fileName: '$fileName',
              originalName: '$original_file_name',
              fileSize: '$file_size',
              pages: '$pages',
            },
          },
        },
      },
      {
        $project: { _id: 0, namespace: '$_id', workspaceName: 1, fileCount: '$count', source: '$sources' },
      },
    ];
    return await client.db().collection('userfiles').aggregate(pipeline).toArray();
  } finally {
    await client.close();
  }
}

// ─── Prompt builders ──────────────────────────────────────────────────────────

function buildSummaryPrompt(custom: string | undefined, separate: boolean): string {
  if (custom?.trim()) {
    return `You are an expert document analyst. Provide a well-structured markdown summary using #### headings. ${custom}`;
  }
  return `You are an expert document analyst and strategic research assistant.

{text}

Provide a well-structured markdown summary:

#### Main Themes
#### Key Points
#### Important Findings
#### Summary
##### Final Executive Summary`;
}

function buildStructuredPrompt(custom: string | undefined): string {
  return `You are an expert document analyst. Generate a structured markdown summary:

#### Main Themes
#### Key Points
#### Important Findings
#### Summary
##### Final Executive Summary

${custom ?? ''}`;
}
